{
"id": "explore",
"title": "Top 10 Routes by Request Volume",
"description": "Counts the total number of requests per route in http_requests, grouped by route, ranked in descending order and limited to the 10 busiest routes.",
"viz": "table",
"layout": {"x": 0, "y": 0, "w": 12, "h": 4},
"query": {
"sourceId": "eval-demo",
"sql": "SELECT route, count(*) AS requests FROM http_requests GROUP BY route ORDER BY requests DESC LIMIT 10"
},
"options": {
"columns": [
{"name": "route", "label": "Route"},
{"name": "requests", "label": "Requests", "format": "number", "decimals": 0, "align": "right"}
],
"sort": {"column": "requests", "order": "desc"}
}
}
